package com.funnywork;

import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:requirements;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","funnywork.bootstrap-token=","funnywork.scheduling-enabled=false","funnywork.execution-enforcement=false"})
@AutoConfigureMockMvc
class MaintenanceRequirementsIntegrationTest {
    @Autowired MaintenanceRequirements requirements;@Autowired MaintenanceService maintenance;@Autowired MaintenanceIntake intake;
    @Autowired AuthService auth;@Autowired JdbcTemplate db;@Autowired Json json;@Autowired MockMvc http;
    @MockBean MaintenanceRemote remote;
    Identity admin;String tenant,repo,token;
    @BeforeEach void setup(){tenant=AuthService.id();token=AuthService.id();auth.create(token,tenant,"USER","Manager",Set.of("ADMIN","OPERATOR","VIEWER"),Set.of("sandbox"),token);admin=auth.authenticate(token);
        repo=(String)maintenance.repository(admin,new MaintenanceService.Repository("example/project","main","sandbox",List.of(new MaintenanceService.Check("diff",List.of("git","diff","--check"),30)))).get("repositoryId");
        intake.configure(admin,new MaintenanceIntake.Configuration(repo,"a".repeat(40),List.of("shared","apps"),true,false,"","macos"));
        db.update("insert into maintenance_automation_policies(repository_id,tenant_id,operator_id,deployment_id,enabled,auto_merge,environment_policy,read_token_ref,delivery_token_ref,reviewer_token_ref,revision,updated_at) values(?,?,?,'model',true,false,'DEVELOPMENT_FUNCTIONAL','FUNNYWORK_GITHUB_READ','FUNNYWORK_GITHUB_WRITE','FUNNYWORK_GITHUB_REVIEW',1,1)",repo,tenant,admin.id());
    }
    MaintenanceRequirements.Draft draft(int version,List<MaintenanceRequirements.Criterion> criteria){return new MaintenanceRequirements.Draft(repo,version,"Preserve saved reports","P1","Keep reports available after reopening","macos",List.of("shared"),criteria,"Clarify behavior");}
    String create(){return (String)requirements.save(admin,null,draft(0,List.of(new MaintenanceRequirements.Criterion(null,"Reopened reports are visible")))).get("id");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> criteria(Map<String,Object> detail){return (List<Map<String,Object>>)((Map<?,?>)detail.get("spec")).get("criteria");}
    Map<String,Object> baseline(){return Map.of("baseSha","a".repeat(40),"files",List.of(Map.of("path","shared/index.ts"),Map.of("path","apps/desktop/main.ts"),Map.of("path","apps/ios/App.swift")),"sourceSnippets",List.of(Map.of("path","apps/desktop/main.ts","content","import { value } from '../../shared/index.ts'")));}
    @Test void stableCriteriaImmutableRevisionsAndOptimisticUpdates(){String id=create();var first=requirements.detail(admin,id);String criterion=(String)criteria(first).get(0).get("id");
        requirements.save(admin,id,draft(1,List.of(new MaintenanceRequirements.Criterion(criterion,"Reopened reports and their status are visible"))));
        var detail=requirements.detail(admin,id);assertEquals(criterion,criteria(detail).get(0).get("id"));assertEquals(2,((List<?>)detail.get("revisions")).size());
        assertEquals("Reopened reports are visible",criteria(first).get(0).get("expected"));assertEquals("REQUIREMENT_VERSION_CHANGED",assertThrows(ApiException.class,()->requirements.save(admin,id,draft(1,List.of(new MaintenanceRequirements.Criterion(criterion,"Stale edit"))))).code);
        assertEquals("REQUIREMENT_CRITERION_INVALID",assertThrows(ApiException.class,()->requirements.save(admin,id,draft(2,List.of(new MaintenanceRequirements.Criterion(AuthService.id(),"Foreign ID"))))).code);
    }
    @Test void queueIsIdempotentAndFreezesDraftWithoutCreatingExecution(){String id=create();var first=(Map<?,?>)requirements.queue(admin,id,new MaintenanceRequirements.Version(1));var retry=(Map<?,?>)requirements.queue(admin,id,new MaintenanceRequirements.Version(1));assertEquals(first.get("intakeId"),retry.get("intakeId"));assertEquals(true,retry.get("reused"));
        assertEquals("QUEUED",requirements.detail(admin,id).get("state"));assertEquals(0,db.queryForObject("select count(*) from tasks where tenant_id=?",Integer.class,tenant));
        assertThrows(ApiException.class,()->intake.detail(admin,(String)first.get("intakeId"),false));
        assertEquals("REQUIREMENT",db.queryForObject("select source_kind from maintenance_intake_sources where intake_id=?",String.class,first.get("intakeId")));
        assertEquals("REQUIREMENT_FROZEN",assertThrows(ApiException.class,()->requirements.save(admin,id,draft(1,List.of(new MaintenanceRequirements.Criterion(null,"Edit"))))).code);
    }
    @Test void impactUsesTransitiveDependenciesAndMarksConfigurationChangesStale()throws Exception{String id=create();var shared=new MaintenanceRequirements.Component("shared","Shared",List.of("shared"),List.of("shared"),List.of());var desktop=new MaintenanceRequirements.Component("desktop","Desktop",List.of("apps/desktop"),List.of("macos","windows"),List.of("shared"));var ios=new MaintenanceRequirements.Component("ios","iOS",List.of("apps/ios"),List.of("ios"),List.of("desktop"));
        requirements.dependencies(admin,repo,new MaintenanceRequirements.DependencyMap(0,List.of(shared,desktop,ios)));when(remote.baseline(anyMap(),anyList())).thenReturn(baseline());
        var impact=(Map<?,?>)requirements.analyze(admin,id,new MaintenanceRequirements.Version(1));var result=(Map<?,?>)impact.get("result");assertEquals(3,((List<?>)result.get("components")).size());assertEquals(false,((Map<?,?>)result.get("coverage")).get("complete"));
        assertEquals(impact.get("id"),((Map<?,?>)requirements.analyze(admin,id,new MaintenanceRequirements.Version(1))).get("id"));
        requirements.dependencies(admin,repo,new MaintenanceRequirements.DependencyMap(1,List.of(shared,desktop)));
        assertEquals("REQUIREMENT_IMPACT_STALE",assertThrows(ApiException.class,()->requirements.assertImpact(admin,id,1,(String)impact.get("id"))).code);
        var detail=requirements.detail(admin,id);assertEquals(true,((Map<?,?>)((List<?>)detail.get("impacts")).get(0)).get("stale"));
        assertEquals("DEPENDENCY_MAP_CHANGED",assertThrows(ApiException.class,()->requirements.dependencies(admin,repo,new MaintenanceRequirements.DependencyMap(1,List.of()))).code);
    }
    @Test void concurrentRequirementEditDuringNetworkReadDiscardsAnalysis()throws Exception{String id=create();String criterion=(String)criteria(requirements.detail(admin,id)).get(0).get("id");when(remote.baseline(anyMap(),anyList())).thenAnswer(inv->{requirements.save(admin,id,draft(1,List.of(new MaintenanceRequirements.Criterion(criterion,"Revised expected behavior"))));return baseline();});
        assertEquals("REQUIREMENT_VERSION_CHANGED",assertThrows(ApiException.class,()->requirements.analyze(admin,id,new MaintenanceRequirements.Version(1))).code);assertEquals(0,db.queryForObject("select count(*) from maintenance_requirement_impacts where requirement_id=?",Integer.class,id));
    }
    @Test void scopedPaginationAndHttpPermissions()throws Exception{String id=create();for(int n=0;n<32;n++)create();var page=(Map<?,?>)requirements.page(admin,"",30,"","","");assertEquals(30,((List<?>)page.get("items")).size());assertFalse(((String)page.get("nextCursor")).isEmpty());assertEquals(3,((List<?>)((Map<?,?>)requirements.page(admin,(String)page.get("nextCursor"),30,"","","")).get("items")).size());
        String otherToken=AuthService.id();auth.create(otherToken,AuthService.id(),"USER","Other",Set.of("ADMIN","OPERATOR"),Set.of("sandbox"),otherToken);assertThrows(ApiException.class,()->requirements.detail(auth.authenticate(otherToken),id));
        String viewer=AuthService.id();auth.create(viewer,tenant,"USER","Viewer",Set.of("VIEWER"),Set.of("sandbox"),viewer);http.perform(get("/api/v1/maintenance/requirements").header("Authorization","Bearer "+viewer)).andExpect(status().isForbidden());
        http.perform(get("/api/v1/maintenance/requirements/"+id).header("Authorization","Bearer "+token)).andExpect(status().isOk());
        http.perform(post("/api/v1/maintenance/requirements").header("Authorization","Bearer "+token).contentType("application/json").content("{} ")).andExpect(status().isBadRequest());
        assertEquals("tasks",ManagementIdentity.module("/api/v1/maintenance/requirements/"+id+"/impact"));assertEquals("agents",ManagementIdentity.module("/api/v1/maintenance/requirement-dependencies/"+repo));
    }
    @Test void unresolvedPathsAndObservedImportsNeverClaimCompleteCoverage(){var baseline=baseline();var result=MaintenanceImpact.analyze(baseline,List.of("shared","missing"),List.of());assertEquals(false,((Map<?,?>)result.get("coverage")).get("complete"));assertEquals(List.of("missing"),result.get("unmatchedPaths"));
        assertTrue(((List<?>)result.get("edges")).stream().anyMatch(e->"SOURCE_IMPORT".equals(((Map<?,?>)e).get("kind"))));assertEquals(2,((List<?>)result.get("components")).size());
    }
    @Test void createRetryNeverDuplicatesRequirement(){var draft=draft(0,List.of(new MaintenanceRequirements.Criterion(null,"Visible after reopening")));var first=(Map<?,?>)requirements.create(admin,"request-one",draft);var retry=(Map<?,?>)requirements.create(admin,"request-one",draft);assertEquals(first.get("id"),retry.get("id"));assertEquals(true,retry.get("reused"));assertEquals(1,db.queryForObject("select count(*) from maintenance_requirements where tenant_id=?",Integer.class,tenant));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(ApiException.class,()->requirements.create(admin,"request-one",draft(0,List.of(new MaintenanceRequirements.Criterion(null,"Different behavior"))))).code);}
    @Test void manualNeedsInformationCreatesAnotherRevisionOfTheSameIntake(){String id=create();var receipt=(Map<?,?>)requirements.queue(admin,id,new MaintenanceRequirements.Version(1));String intakeId=(String)receipt.get("intakeId");db.update("update maintenance_intakes set state='NEEDS_INFORMATION' where id=?",intakeId);String criterion=(String)criteria(requirements.detail(admin,id)).get(0).get("id");requirements.save(admin,id,draft(1,List.of(new MaintenanceRequirements.Criterion(criterion,"Reports include restored status"))));var detail=requirements.detail(admin,id);assertEquals(2,detail.get("version"));assertEquals(intakeId,detail.get("intake_id"));assertEquals("QUEUED",detail.get("state"));assertEquals(2,db.queryForObject("select revision from maintenance_intakes where id=?",Integer.class,intakeId));assertEquals(1,db.queryForObject("select count(*) from maintenance_intakes where tenant_id=?",Integer.class,tenant));}
    @Test void productRequirementsSurviveTechnicalFailureAndRetainCriterionIdentityOnReanalysis(){String intakeId=(String)((Map<?,?>)intake.feedback(admin,new MaintenanceIntake.Feedback(repo,"product","Saved reports","Missing report","Visible report","Reopen","macos","1"))).get("intakeId");var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var product=mapper.valueToTree(Map.of("title","Persist reports","requirement","Restore report history","acceptance","Report is visible after reopening"));var captured=requirements.capture(admin,db.queryForMap("select * from maintenance_intakes where id=?",intakeId),product);String id=(String)captured.get("id");String criterion=(String)criteria(requirements.detail(admin,id)).get(0).get("id");assertEquals(0,db.queryForObject("select count(*) from tasks where tenant_id=?",Integer.class,tenant));db.update("update maintenance_intakes set revision=2 where id=?",intakeId);((com.fasterxml.jackson.databind.node.ObjectNode)product).put("acceptance","Report and status are restored");requirements.capture(admin,db.queryForMap("select * from maintenance_intakes where id=?",intakeId),product);assertEquals(2,requirements.detail(admin,id).get("version"));assertEquals(criterion,criteria(requirements.detail(admin,id)).get(0).get("id"));}
    @Test void historicalImportDoesNotCreateTasksAndIsRepeatable(){String intakeId=(String)((Map<?,?>)intake.feedback(admin,new MaintenanceIntake.Feedback(repo,"historical","Old report","Missing report","Visible report","Reopen","macos","1"))).get("intakeId");db.update("update maintenance_intakes set state='READY_FOR_REVIEW',analysis_json=? where id=?",json.write(Map.of("title","Old requirement","requirement","Restore reports","acceptance","Report reopens")),intakeId);var imported=(Map<?,?>)requirements.importExisting(admin,"");assertEquals(1,imported.get("imported"));assertEquals(0,((Map<?,?>)requirements.importExisting(admin,"")).get("imported"));assertEquals(0,db.queryForObject("select count(*) from tasks where tenant_id=?",Integer.class,tenant));}

    @Test void overlappingComponentMapsCannotProduceUnboundedSourceEdges(){var components=new ArrayList<Map<String,Object>>();for(int n=0;n<80;n++)components.add(Map.of("key","component-"+n,"name","Component "+n,"paths",List.of("apps","shared"),"platforms",List.of("shared"),"dependsOn",List.of()));var baseline=new LinkedHashMap<>(baseline());baseline.put("sourceSnippets",List.of(Map.of("path","apps/desktop/main.ts","content","import a from '../../shared/index.ts'; import b from '../../shared/index.ts'; import c from '../../shared/index.ts';")));var result=MaintenanceImpact.analyze(baseline,List.of("shared"),components);assertTrue(((List<?>)result.get("edges")).size()<=8000);assertTrue(((List<?>)result.get("warnings")).contains("DEPENDENCY_EDGE_LIMIT"));assertEquals(80,((List<?>)result.get("components")).size());}

    @Test void manualRequirementCanBeRetriedFromFeedbackWithoutLosingItsProductFields(){String requirement=create();String id=(String)((Map<?,?>)requirements.queue(admin,requirement,new MaintenanceRequirements.Version(1))).get("intakeId");db.update("update maintenance_intakes set state='NEEDS_INFORMATION' where id=?",id);assertEquals(true,((Map<?,?>)intake.retry(admin,id)).get("queued"));assertEquals(2,db.queryForObject("select revision from maintenance_intakes where id=?",Integer.class,id));assertTrue(db.queryForObject("select body from maintenance_intakes where id=?",String.class,id).contains("Reopened reports are visible"));assertEquals(1,requirements.detail(admin,requirement).get("version"));}
    @Test void runningBackendAnalysisCannotBeInvalidatedByFeedbackRetry(){String requirement=create();String id=(String)((Map<?,?>)requirements.queue(admin,requirement,new MaintenanceRequirements.Version(1))).get("intakeId");db.update("insert into maintenance_stage_runs(id,tenant_id,repository_id,subject_id,stage,input_hash,input_json,policy_revision,state,created_at,updated_at) values(?,?,?,?,'PRODUCT',?,'{}',1,'RUNNING',1,1)",AuthService.id(),tenant,repo,id+":1","a".repeat(64));assertEquals("INTAKE_ANALYSIS_ACTIVE",assertThrows(ApiException.class,()->intake.retry(admin,id)).code);assertEquals(1,db.queryForObject("select revision from maintenance_intakes where id=?",Integer.class,id));}

}
